package vn.tuan.service;
import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.time.*;import java.util.*;import vn.tuan.repository.*;import vn.tuan.service.*;
@org.springframework.stereotype.Service @RequiredArgsConstructor public class ApiService {
 private final AccountRepository accounts;private final OrderRepository orders;private final JwtEncoder encoder;private final PasswordEncoder passwords;private final ActorService actors;
 public record Login(String email,String password){}
 public Map<String,Object> token(Login in){var a=accounts.findByEmail(in.email()==null?"":in.email().trim().toLowerCase(Locale.ROOT)).orElse(null);if(a==null || in.password()==null || !Boolean.TRUE.equals(a.getIsActive()) || !passwords.matches(in.password(),a.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Thông tin đăng nhập không hợp lệ");var now=Instant.now();var claims=JwtClaimsSet.builder().issuer("utetra").subject(a.getEmail()).issuedAt(now).expiresAt(now.plusSeconds(900)).claim("role",actors.role(a)).claim("credential",fingerprint(a.getPassword())).build();String jwt=encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),claims)).getTokenValue();return Map.of("access_token",jwt,"token_type","Bearer","expires_in",900);}
 public Object myOrders(Jwt jwt){var a=actors.account(jwt.getSubject());if(!fingerprint(a.getPassword()).equals(jwt.getClaimAsString("credential")))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return orders.findByAccountOrderByCreatedAtDesc(a).stream().map(o->Map.of("id",o.getId(),"status",o.getStatus(),"amount",o.getFinalAmount())).toList();}
 private String fingerprint(String password){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(password.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
